const V = (name, lang) => ({ name, lang, localService: true, default: name === 'Samantha', voiceURI: 'com.apple.voice.compact.' + lang + '.' + name.split(' ')[0] });
window.__voices = [
  V('Samantha', 'en-US'), V('Daniel', 'en-GB'), V('Karen', 'en-AU'), V('Moira', 'en-IE'), V('Rishi', 'en-IN'), V('Tessa', 'en-ZA'),
  V('Fred', 'en-US'), V('Albert', 'en-US'), V('Bad News', 'en-US'), V('Bahh', 'en-US'), V('Bells', 'en-US'), V('Boing', 'en-US'),
  V('Bubbles', 'en-US'), V('Cellos', 'en-US'), V('Good News', 'en-US'), V('Jester', 'en-US'), V('Junior', 'en-US'), V('Kathy', 'en-US'),
  V('Organ', 'en-US'), V('Ralph', 'en-US'), V('Superstar', 'en-US'), V('Trinoids', 'en-US'), V('Whisper', 'en-US'), V('Wobble', 'en-US'), V('Zarvox', 'en-US'),
  V('Eddy (English (US))', 'en-US'), V('Flo (English (US))', 'en-US'), V('Grandma (English (US))', 'en-US'), V('Grandpa (English (US))', 'en-US'),
  V('Reed (English (US))', 'en-US'), V('Rocko (English (US))', 'en-US'), V('Sandy (English (US))', 'en-US'), V('Shelley (English (US))', 'en-US'),
  V('Alva', 'sv-SE'), V('Thomas', 'fr-FR'), V('Anna', 'de-DE')
];
window.__spoken = [];
SpeechSynthesis.prototype.getVoices = function () { return window.__voices; };
SpeechSynthesis.prototype.speak = function (u) { window.__spoken.push({ text: u.text, voice: u.voice ? u.voice.name : 'device default', lang: u.lang, rate: u.rate, pitch: u.pitch }); };
SpeechSynthesis.prototype.cancel = function () {};
window.SpeechSynthesisUtterance = class { constructor(t) { this.text = t; } };
const st = window.setTimeout; window.setTimeout = (f, ms, ...a) => st(f, ms >= 5000 ? ms * 10 : ms, ...a);
